style.css:
@-moz-document domain("roblox.com") {
/* Set custom background image */
    body {
        background: url("https://i.pinimg.com/736x/96/72/81/967281b35c2ed4376eab2a00bb96b95b.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
        color: #e0e0e0 !important;
    }

    /* Make content panels semi-transparent so background shows */
    .card, .container, .section, .content, .rbx-navbar, .navbar {
        background-color: rgba(18, 18, 18, 0.85) !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
    }

    /* Links */
    a {
        color: #4da3ff !important;
    }
    a:hover {
        color: #82c7ff !important;
    }

    /* Buttons */
    .btn-primary {
        background-color: #4da3ff !important;
        border-color: #4da3ff !important;
        color: #fff !important;
    }
    .btn-primary:hover {
        background-color: #82c7ff !important;
        border-color: #82c7ff !important;
    }

    /* Inputs */
    input, textarea, select {
        background-color: rgba(34, 34, 34, 0.85) !important;
        color: #fff !important;
        border: 1px solid #444 !important;
    }
}
